package com.shivhub.backend.controller;
import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import com.shivhub.backend.dto.*; import com.shivhub.backend.entity.User; import com.shivhub.backend.repository.UserRepository; import com.shivhub.backend.service.CustomerReceivableService; import lombok.RequiredArgsConstructor;
@RestController @RequestMapping("/api/customer-receivables") @CrossOrigin(origins="*") @RequiredArgsConstructor public class CustomerReceivableController { private final CustomerReceivableService service; private final UserRepository users; private User seller(Authentication a){return users.findByEmail(a.getName()).orElseThrow(()->new RuntimeException("Seller not found"));} @GetMapping public List<Map<String,Object>> list(Authentication a){return service.list(seller(a));} @PostMapping public ResponseEntity<?> create(Authentication a,@RequestBody CustomerReceivableRequest r){try{return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r,seller(a)));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}} @PostMapping("/{id}/payments") public ResponseEntity<?> pay(@PathVariable Long id,Authentication a,@RequestBody CustomerPaymentRequest r){try{return ResponseEntity.status(HttpStatus.CREATED).body(service.receive(id,r,seller(a)));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}} @PutMapping("/{id}/due-date") public ResponseEntity<?> reviseDueDate(@PathVariable Long id, Authentication a, @RequestBody CustomerDueDateRequest r){try{return ResponseEntity.ok(service.reviseDueDate(id,r,seller(a)));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}} @GetMapping("/{id}/payments") public ResponseEntity<?> history(@PathVariable Long id,Authentication a){try{return ResponseEntity.ok(service.history(id,seller(a)));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}} }
